def design(feats) -> Design:
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    if p == 0 or np.unique(y).size < 2 or MAX_DRIVERS < 1:
        return Design(drivers=(), columns=(), products=(), loadings={})
    ids = tuple(feats.ids); labels = list(dict.fromkeys(feats.stratum))
    S = np.array([[s == t for t in labels[1:]] for s in feats.stratum], float).reshape(n, -1)
    C = [j for j, t in enumerate(feats.types) if str(t).lower() in ('clinical', 'cohort')]
    R = np.nan_to_num(np.corrcoef(X, rowvar=False)); R = np.atleast_2d(R)
    C = sorted(C, key=lambda j: -np.sum(R[j] ** 2))[:min(16, max(1, n // 30))]
    B = np.column_stack([np.ones(n), S]); sel = []; prods = []
    def matrix(s, q, clinical=C):
        z = [X[:, j] for j in dict.fromkeys(clinical + s)]
        z += [X[:, j] ** 2 for j in clinical] + [X[:, a] * X[:, b] for a, b in q]
        return np.column_stack([B] + z)
    def fit(A):
        b = np.zeros(A.shape[1]); penalty = 1e-6 * np.eye(A.shape[1])
        def loss(v):
            e = A @ v
            return np.sum(y * e - np.logaddexp(0, e)) - 5e-7 * (v @ v)
        for _ in range(40):
            m = 1 / (1 + np.exp(-np.clip(A @ b, -30, 30))); w = m * (1 - m) + 1e-9
            H = A.T @ (w[:, None] * A) + penalty
            step = np.linalg.solve(H, A.T @ (y - m) - 1e-6 * b); scale = 1.
            while scale > 1e-5 and loss(b + scale * step) < loss(b): scale *= .5
            b += scale * step
            if np.max(np.abs(scale * step)) < 1e-7: break
        m = 1 / (1 + np.exp(-np.clip(A @ b, -30, 30))); w = m * (1 - m) + 1e-9
        return loss(b), m, w, np.linalg.pinv(A.T @ (w[:, None] * A) + penalty)
    def scores(Z, A, state):
        _, m, w, H = state; V = A.T @ (w[:, None] * Z)
        v = np.sum(w[:, None] * Z ** 2, axis=0) - np.sum(V * (H @ V), axis=0)
        return (Z.T @ (y - m)) ** 2 / np.maximum(v, 1e-9)
    for _ in range(MAX_DRIVERS):
        A = matrix(sel, prods); state = fit(A); sc = scores(X, A, state)
        choices = [j for j in np.argsort(-sc) if j not in C + sel
                   and not any(abs(R[j, k]) > .85 for k in sel)]
        cand = [(fit(matrix(sel + [j], prods))[0], j) for j in choices[:12]]
        if not cand: break
        value, j = max(cand)
        if stats.chi2.sf(max(0, 2 * (value - state[0])), 1) > .1 / p: break
        sel.append(j)
    pairs = [(a, b) for a in range(p) for b in range(a, p) if not (a == b and a in C)]
    A = matrix(sel, prods); state = fit(A); ranked = []
    for start in range(0, len(pairs), 256):
        batch = pairs[start:start + 256]; Z = np.column_stack([X[:, a] * X[:, b] for a, b in batch])
        sc = scores(Z, A, state); ranked += [(sc[i], a, b) for i, (a, b) in enumerate(batch)]
    for _, a, b in sorted(ranked, reverse=True)[:12]:
        mains = sorted(set(sel + [a, b]) - set(C)); q = prods + [(a, b)]
        gain = 2 * (fit(matrix(mains, q))[0] - fit(matrix(mains, prods))[0])
        if stats.chi2.sf(max(0, gain), 1) < .01 / max(1, len(pairs)):
            if not any({a, b} & {c, d} for c, d in prods): prods.append((a, b))
        if len(prods) == 2: break
    mains = sorted(set(sel + [j for pair in prods for j in pair]) - set(C))
    state = fit(matrix(mains, prods)); evidence = []
    for j in C + mains:
        if j in C:
            rest = matrix(mains, prods, [k for k in C if k != j]); df = 2
        else:
            rest = matrix([k for k in mains if k != j], prods); df = 1
        pv = stats.chi2.sf(max(0, 2 * (state[0] - fit(rest)[0])), df)
        if pv < .1 / p: evidence.append((pv, j))
    for a, b in prods:
        pv = stats.chi2.sf(max(0, 2 * (state[0] - fit(matrix(mains, [q for q in prods if q != (a, b)]))[0])), 1)
        if pv < .01 / max(1, len(pairs)): evidence += [(pv, a), (pv, b)]
    drivers = []
    for pv, j in sorted(evidence):
        if j not in drivers and not any(abs(R[j, k]) > .85 for k in drivers): drivers.append(j)
    drivers = drivers[:MAX_DRIVERS]
    columns = tuple(ids[j] for j in sorted(set(C + mains))) if drivers else ()
    products = tuple((ids[j], ids[j]) for j in C) + tuple((ids[a], ids[b]) for a, b in prods)
    return Design(drivers=tuple(ids[j] for j in drivers), columns=columns,
                  products=products if drivers else (), loadings={})

